    /**
     * 为 asset 生成 assetId；priorAssetType 为优先的资产类型，决定 assetId 是否带类型信息。
     * @param asset 指定的资产
     * @param usedAssetIdArray 已使用的 assetId 数组
     * @param priorAssetType 优先的资产类型，null 代表 ".*"，意味生成的 assetId 总是带类型信息
     */
    @JvmStatic
    fun generateAssetId(asset: String, usedAssetIdArray: List<String>?, priorAssetType: String?): String {
        val assetFile = File(asset)
        val fileExtName = FlrFileUtil.getFileExtension(assetFile).lowercase()
        val fileBasenameWithoutExtension = FlrFileUtil.getFileBasenameWithoutExtension(assetFile)

        var assetId = fileBasenameWithoutExtension
        if (priorAssetType == null || priorAssetType != fileExtName) {
            val extInfo = "_" + fileExtName.substring(1)
            assetId = fileBasenameWithoutExtension + extInfo
        }

        // 过滤非法字符
        assetId = assetId.replace("[^a-zA-Z0-9_\$]".toRegex(), "_")

        // 检测首字符是不是字母；是大写字母则转小写；不是字母则加前缀 "a"
        val firstChar = assetId[0]
        if (Character.isLetter(firstChar)) {
            if (Character.isUpperCase(firstChar)) {
                val firstCharStr = firstChar.toString().lowercase()
                assetId = firstCharStr + assetId.substring(1)
            }
        } else {
            val firstCharStr = "a"
            assetId = firstCharStr + assetId
        }

        // 处理 asset_id 重名的情况
        if (usedAssetIdArray != null && usedAssetIdArray.isEmpty() == false && usedAssetIdArray.contains(assetId)) {
            var repeatCount = 1

            // 查找当前 asset_id 衍生出来的 asset_id_brother：#{asset_id}$#{repeat_count}（repeat_count >= 1）
            val idBrotherRegex = String.format("^%s\\\$[1-9][0-9]*\$", assetId)
            val pattern = Pattern.compile(idBrotherRegex)
            val curAssetIdBrothers = usedAssetIdArray.stream().filter(pattern.asPredicate()).collect(Collectors.toList())

            if (curAssetIdBrothers != null && curAssetIdBrothers.isEmpty() == false) {
                repeatCount += curAssetIdBrothers.size
            }

            assetId = String.format("%s\$%d", assetId, repeatCount)
        }

        return assetId
    }

    /**
     * 为当前 asset 生成注释。
     * 例：packageName="flutter_r_demo"，asset="packages/flutter_r_demo/assets/images/test.png"
     * -> "asset: lib/assets/images/test.png"
     */
    @JvmStatic
    fun generateAssetComment(asset: String, packageName: String): String {
        val packagesPrefix = "packages/$packageName/"

        return if (asset.startsWith(packagesPrefix)) {
            val assetName = asset.replaceFirst(packagesPrefix, "")
            "asset: lib/$assetName"
        } else {
            "asset: $asset"
        }
    }

    /** 为当前 asset 生成 AssetResource property 的代码 */
    @JvmStatic
    fun generate_AssetResource_property(
        asset: String,
        assetIdDict: Map<String, String>,
        packageName: String,
        isPackageProjectType: Boolean,
        priorAssetType: String?
    ): String {
        val assetId = assetIdDict[asset]
        val assetComment = generateAssetComment(asset, packageName)

        var assetName = ""
        var needPackage: Boolean

        val packagesPrefix = "packages/$packageName/"
        if (asset.startsWith(packagesPrefix)) {
            assetName = asset.replaceFirst(packagesPrefix, "")
            needPackage = true
        } else {
            assetName = asset
            needPackage = isPackageProjectType
        }

        // 对字符串中的 '$' 进行转义处理：'$' -> '\$'
        val escapedAssetName = assetName.replace("\$", "\\\$")

        return if (needPackage) {
            String.format(
                "  /// %s\n" +
                    "  // ignore: non_constant_identifier_names\n" +
                    "  final %s = const AssetResource(\"%s\", packageName: R.package);",
                assetComment,
                assetId,
                escapedAssetName
            )
        } else {
            String.format(
                "  /// %s\n" +
                    "  // ignore: non_constant_identifier_names\n" +
                    "  final %s = const AssetResource(\"%s\", packageName: null);",
                assetComment,
                assetId,
                escapedAssetName
            )
        }
    }

    /** 根据模板，为 nonSvgImageAssetArray 生成 _R_Image_AssetResource class 的代码 */
    @JvmStatic
    fun generate__R_Image_AssetResource_class(
        nonSvgImageAssetArray: List<String>,
        nonSvgImageAssetIdDict: Map<String, String>,
        packageName: String,
        isPackageProjectType: Boolean
    ): String {
        var allPropertyCode = ""
        for (asset in nonSvgImageAssetArray) {
            allPropertyCode += "\n"
            allPropertyCode += generate_AssetResource_property(
                asset, nonSvgImageAssetIdDict, packageName, isPackageProjectType, FlrConstant.PRIOR_NON_SVG_IMAGE_FILE_TYPE
            )
        }
        return String.format(
            "// ignore: camel_case_types\n" +
                "class _R_Image_AssetResource {\n" +
                "  const _R_Image_AssetResource();\n" +
                "%s\n" +
                "}",
            allPropertyCode
        )
    }

